from copy import deepcopy
import pytest
from ark_sim import Compiler,Engine
from ark_sim.domains.selection import DEFAULT_STATE,SWITCHES
from ark_sim.contracts import thaw
from ark_sim.tools.replay import replay
from tools.campaign_ordered_checkpoint import write_ordered,load_bound
INPUTS=[];CAPTURES=[]
def package(flag=True):
 p={'schemaVersion':2,'manifest':{'id':'package/peer/realtiles','requires':['preset/ark_standard']},'rules':[{'id':'rule/peer/tileselect','kind':'rule','contract':'targeting.eligibility','implementation':{'type':'graph','nodes':[{'id':'answer','expression':"{'accepted':inputs.candidate_spatial_tile.tile.buildableType == 2,'reason':'actual_tile_mask'}"}],'output':'nodes.answer'}}],'selectors':[{'id':'selector/peer/tile','kind':'selector','region':{'type':'radius','radius':4},'filters':[{'tag':'player'}],'limit':None,'eligibility':{'rule':'rule/peer/tileselect','parameters':{'source_configuration':{**{k:0 for k in SWITCHES},'_targetSide':2,'_targetMotion':1,'_targetCategory':1},'side_policy':'relative_ally_enemy','neutral_policy':'reject','defaults':deepcopy(DEFAULT_STATE)},'include_candidate_tile':flag}}],'entities':[{'id':'unit/peer/source','kind':'entity','tags':['enemy'],'components':{'selection_state':{'side':1,'motion':1,'category':1},'spatial':{}}},{'id':'unit/peer/highGround','kind':'entity','tags':['player','ground'],'components':{'selection_state':{'side':0,'motion':1,'category':1},'spatial':{}}},{'id':'unit/peer/lowRanged','kind':'entity','tags':['player','ranged'],'components':{'selection_state':{'side':0,'motion':1,'category':1},'spatial':{}}}],'scenarioDraft':{'id':'scene/peer/realtiles','ruleset':'ruleset/ark_standard','map':{'rows':1,'cols':3,'tiles':[{'tileKey':'tile_floor','buildableType':1,'heightType':0,'passableMask':1},{'tileKey':'tile_floor','buildableType':2,'heightType':1,'passableMask':1},{'tileKey':'tile_floor','buildableType':1,'heightType':0,'passableMask':1}]},'objectives':{},'initialEntities':[{'definition':'unit/peer/source','instanceAlias':'source','position':{'row':0,'col':0}},{'definition':'unit/peer/highGround','instanceAlias':'groundOnHigh','position':{'row':0,'col':1}},{'definition':'unit/peer/lowRanged','instanceAlias':'rangedOnLow','position':{'row':0,'col':2}}],'dependencies':['selector/peer/tile']}}
 return p
def make(p):INPUTS.append(deepcopy(p));return Engine.create(Compiler().compile(p))
def capture(s,k):CAPTURES.append({'case':k,'checkpoint':s.checkpoint(),'events':thaw(tuple(s.session.events)),'snapshot':s.snapshot(),'commands':s.export_replay()})
def test_actual_tile_mask_selects_ground_on_highland_not_ranged_label_pure():
 s=make(package());before=s.checkpoint();selector=s.program.definitions['selector/peer/tile'];assert s.ctx.spatial.qualifies('source',s.session.world.resolve('groundOnHigh'),selector) and not s.ctx.spatial.qualifies('source',s.session.world.resolve('rangedOnLow'),selector);assert s.checkpoint()==before;capture(s,'tile_vs_label')
@pytest.mark.parametrize('flag',[0,1,None,'true',[]])
def test_optin_flag_is_strict_boolean(flag):
 with pytest.raises(ValueError):Compiler().compile(package(flag))
def test_optin_false_does_not_invent_tile_fields():
 p=package(False);p['rules'][0]['implementation']['nodes'][0]['expression']="{'accepted':'candidate_spatial_tile' not in inputs,'reason':'no_optin'}";s=make(p);assert len(s.ctx.spatial.select('source','selector/peer/tile'))==2;capture(s,'noopt_shape')

def test_public_query_after_real_terrain_overlay_uses_current_grid_and_disk_head(tmp_path):
 p=package();p['abilities']=[{'id':'ability/peer/overlay','kind':'ability','activation':{'mode':'manual','on_start':[{'op':'apply_terrain_overlay','parameters':{'key':'source_override','priority':2,'position':{'row':0,'col':2},'values':{'buildableType':2,'heightType':1},'preserve':['passableMask']}}]},'timeline':[]},{'id':'ability/peer/query','kind':'ability','activation':{'mode':'manual'},'selector':'selector/peer/tile','timeline':[{'at':0,'effect':{'op':'emit','event':'peer.tile.query'}}]}];p['entities'][0]['components']['abilities']=['ability/peer/overlay','ability/peer/query'];s=make(p);s.submit({'action':'skill','source':'source','ability':'ability/peer/overlay'},at=2);s.submit({'action':'skill','source':'source','ability':'ability/peer/query'},at=3);s.advance(1);path=tmp_path/'tile_before_overlay.json';pin=write_ordered(path,s.checkpoint());rest=Engine.restore(s.program,load_bound(path,pin));s.advance(4);rest.advance(4);head=replay(s.program,s.export_replay());capture(s,'actual_current_overlay');assert s.checkpoint()==rest.checkpoint()==head.checkpoint() and thaw(tuple(s.session.events))==thaw(tuple(head.session.events))
 starts=[e for e in s.session.events if e['type']=='ability.started' and e['payload']['ability']=='ability/peer/query'];assert starts and list(starts[0]['payload']['targets'])==[s.session.world.resolve('groundOnHigh'),s.session.world.resolve('rangedOnLow')]
